// ========== 推荐修复方案 1：使用参数化命令（spawn）==========

import { spawn } from "child_process"

/**
 * 安全方案：使用 spawn 以非 shell 模式执行命令
 * 避免了 shell 解析风险，且可以对命令和参数进行严格控制
 */
export function getConfigValueSafe(key: string): void {
	// 1. 从环境变量获取，但仅作为配置键使用，不直接作为命令
	const configCmd = process.env[`CONFIG_CMD_${key}`]

	if (!configCmd) {
		return
	}

	// 2. 使用白名单验证，只允许预定义的安全命令
	const ALLOWED_COMMANDS = {
		"reload_config": "/usr/bin/reload",
		"update_cache": "/usr/bin/update-cache",
		"cleanup_logs": "/usr/bin/logcleaner"
	}

	const allowedCmd = ALLOWED_COMMANDS[configCmd]
	if (!allowedCmd) {
		console.error(`不允许的配置命令: ${configCmd}`)
		return
	}

	// 3. 使用 spawn 以数组形式传递命令和参数
	// 这会禁用 shell 解析，防止命令注入
	spawn(allowedCmd, [], {
		stdio: 'inherit',
		shell: false  // 明确禁用 shell
	}).on('error', (err) => {
		console.error(`命令执行失败: ${err.message}`)
	})
}

