export function getConfigValueSafeV2(key: string): void {
	// 1. 从环境变量获取操作类型
	const actionType = process.env[`CONFIG_CMD_${key}`]

	if (!actionType) {
		return
	}

	// 2. 验证操作类型是否在白名单中
	const action = CONFIG_ACTIONS[actionType as keyof typeof CONFIG_ACTIONS]
	if (!action) {
		console.error(`未知的配置操作: ${actionType}`)
		return
	}

	// 3. 使用参数化执行，禁止 shell 解析
	spawn(action.command, action.args, {
		stdio: 'inherit',
		shell: false,
		...process.env  // 仅传递必要的权限环境变量
	}).on('error', (err) => {
		console.error(`操作失败: ${action.description} - ${err.message}`)
	})
}

