import { ConfigService } from './config-service'

export class AppConfigManager {
	private configService: ConfigService = new ConfigService()

	/**
	 * 安全配置更新方法
	 * 所有配置操作都通过配置服务统一管理
	 */
	async reloadConfig(key: string): Promise<boolean> {
		// 仅允许从受信的配置源（如数据库、加密配置文件）读取
		const config = await this.configService.getConfig(key)

		if (!config.enabled || !appConfig.enabledActions.includes(config.action)) {
			return false
		}

		// 使用预定义的安全操作
		const action = CONFIG_ACTIONS[config.action]
		if (!action) {
			return false
		}

		return new Promise((resolve) => {
			const process = spawn(action.command, action.args, {
				stdio: 'inherit',
				shell: false
			})

			process.on('close', (code) => {
				resolve(code === 0)
			})

			process.on('error', () => {
				resolve(false)
			})
		})
	}
}

