	const SAFE_PATTERN = /^[a-zA-Z0-9_.-]+$/
	if (!SAFE_PATTERN.test(configCmd)) {
		console.error(`配置命令包含非法字符: ${configCmd}`)
		return
	}

	// 2. 长度限制
	if (configCmd.length > 100) {
		console.error(`配置命令过长: ${configCmd}`)
		return
	}

	// 3. 使用 shell: false 执行
	spawn(configCmd, [], {
		stdio: 'inherit',
		shell: false  // 禁用 shell，防止命令注入
	}).on('error', (err) => {
		console.error(`命令执行失败: ${err.message}`)
	})

